async function enqueueTelegramOutbox(input) {
  try {
    await db.insert(telegramOutbox).values({
      orderId: input.orderId,
      orderNumber: input.orderNumber,
      status: "pending",
      lastError: input.reason ?? null,
      nextAttemptAt: sql5`now()`
    }).onConflictDoUpdate({
      target: telegramOutbox.orderId,
      set: {
        status: "pending",
        attempts: 0,
        lastError: input.reason ?? null,
        nextAttemptAt: sql5`now()`,
        updatedAt: sql5`now()`
      }
    });
  } catch (e) {
    console.warn(
      `[telegram-outbox] could not queue a retry for ${input.orderNumber}: ${e.message}`
    );
  }
}
