async function recordTelegramOutboxFailure(id, error, maxAttempts) {
  const [row] = await db.select({ attempts: telegramOutbox.attempts }).from(telegramOutbox).where(eq3(telegramOutbox.id, id)).limit(1);
  const attempts = row?.attempts ?? maxAttempts;
  const giveUp = attempts >= maxAttempts;
  await db.update(telegramOutbox).set({
    status: giveUp ? "failed" : "pending",
    lastError: error,
    updatedAt: sql5`now()`
  }).where(eq3(telegramOutbox.id, id));
  return { status: giveUp ? "failed" : "pending", attempts };
}
