async function adminStats(lowStockThreshold = LOW_STOCK_THRESHOLD) {
  const paid = and3(eq3(orders.paymentStatus, "paid"), ne(orders.status, "cancelled"));
  const [revenueRow] = await db.select({ value: sql5`coalesce(sum(${orders.totalCents}), 0)::int` }).from(orders).where(paid);
  const [orderCountRow] = await db.select({ value: count() }).from(orders);
  const [openRow] = await db.select({ value: count() }).from(orders).where(inArray2(orders.status, ["pending", "paid", "processing"]));
  const [userRow] = await db.select({ value: count() }).from(users);
  const [customerRow] = await db.select({ value: sql5`count(distinct ${orders.userId})::int` }).from(orders).where(paid);
  const [reviewRow] = await db.select({ value: count() }).from(reviews);
  const [productRow] = await db.select({ value: count() }).from(products).where(and3(eq3(products.active, true), eq3(products.archived, false)));
  const [pendingReviewRow] = await db.select({ value: count() }).from(reviews).where(eq3(reviews.status, "pending"));
  const [newMessageRow] = await db.select({ value: count() }).from(contactMessages).where(eq3(contactMessages.status, "new"));
  const [subscriberRow] = await db.select({ value: count() }).from(newsletterSubscribers).where(eq3(newsletterSubscribers.status, "subscribed"));
  const [paidOrderRow] = await db.select({ value: count() }).from(orders).where(paid);
  const revenueByDay = await db.execute(sql5`
    with days as (
      select generate_series(
        date_trunc('day', now()) - interval '13 days',
        date_trunc('day', now()),
        interval '1 day'
      ) as day
    )
    select
      to_char(days.day, 'YYYY-MM-DD') as date,
      coalesce(sum(${orders.totalCents}), 0)::int as cents
    from days
    left join ${orders}
      on date_trunc('day', ${orders.createdAt}) = days.day
      and ${orders.paymentStatus} = 'paid'
      and ${orders.status} <> 'cancelled'
    group by days.day
    order by days.day
  `);
  const revenueSeries = rowsOf(revenueByDay).map((r) => ({
    date: String(r.date),
    cents: Number(r.cents ?? 0)
  }));
  const [lowStockCountRow] = await db.select({ value: count() }).from(productVariants).where(and3(eq3(productVariants.active, true), lte(productVariants.inventoryQty, lowStockThreshold)));
  const lowStock = await db.select({
    id: productVariants.id,
    productId: productVariants.productId,
    name: productVariants.name,
    sku: productVariants.sku,
    inventoryQty: productVariants.inventoryQty,
    productName: products.name
  }).from(productVariants).innerJoin(products, eq3(productVariants.productId, products.id)).where(and3(eq3(productVariants.active, true), lte(productVariants.inventoryQty, lowStockThreshold))).orderBy(asc(productVariants.inventoryQty)).limit(8);
  const recentOrders = await db.select().from(orders).orderBy(desc(orders.createdAt)).limit(8);
  const topProducts = await db.select({
    name: orderItems.nameSnapshot,
    slug: orderItems.slug,
    units: sql5`sum(${orderItems.qty})::int`,
    revenue: sql5`sum(${orderItems.qty} * ${orderItems.priceCents})::int`
  }).from(orderItems).innerJoin(orders, eq3(orderItems.orderId, orders.id)).where(paid).groupBy(orderItems.nameSnapshot, orderItems.slug).orderBy(desc(sql5`sum(${orderItems.qty} * ${orderItems.priceCents})`)).limit(5);
  const [rev30Row] = await db.select({ value: sql5`coalesce(sum(${orders.totalCents}), 0)::int` }).from(orders).where(and3(paid, gte(orders.createdAt, sql5`now() - interval '30 days'`)));
  const [revPrev30Row] = await db.select({ value: sql5`coalesce(sum(${orders.totalCents}), 0)::int` }).from(orders).where(
    and3(
      paid,
      gte(orders.createdAt, sql5`now() - interval '60 days'`),
      sql5`${orders.createdAt} < now() - interval '30 days'`
    )
  );
  const paidOrders = paidOrderRow?.value ?? 0;
  return {
    revenueCents: revenueRow?.value ?? 0,
    revenue30dCents: rev30Row?.value ?? 0,
    revenuePrev30dCents: revPrev30Row?.value ?? 0,
    orderCount: orderCountRow?.value ?? 0,
    openOrders: openRow?.value ?? 0,
    customerCount: customerRow?.value ?? 0,
    userCount: userRow?.value ?? 0,
    reviewCount: reviewRow?.value ?? 0,
    productCount: productRow?.value ?? 0,
    pendingReviews: pendingReviewRow?.value ?? 0,
    newMessages: newMessageRow?.value ?? 0,
    subscriberCount: subscriberRow?.value ?? 0,
    averageOrderCents: paidOrders > 0 ? Math.round((revenueRow?.value ?? 0) / paidOrders) : 0,
    revenueByDay: revenueSeries,
    lowStock,
    lowStockCount: lowStockCountRow?.value ?? 0,
    recentOrders,
    topProducts
  };
}
