async function countProviderRows(sqlText) {
  const res = await db.execute(sqlText);
  const rows = rowsOf(res);
  const first = rows[0];
  return first ? Number(first.n ?? 0) : 0;
}
async function deleteUserAccount(userId) {
  const [row] = await db.select({
    id: users.id,
    email: users.email,
    role: users.role,
    neonAuthUserId: users.neonAuthUserId
  }).from(users).where(eq3(users.id, userId)).limit(1);
  if (!row) return null;
  if (isAdminRole(row.role)) throw new AdminDeleteRefusedError();
  const neonAuth = { users: 0, sessions: 0, accounts: 0, members: 0, invitations: 0, verifications: 0 };
  const neonId = row.neonAuthUserId;
  const isUuid = (v) => typeof v === "string" && /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v);
  if (isUuid(neonId)) {
    try {
      for (const { table, column } of NEON_AUTH_IDENTITY_TABLES) {
        const before = await countProviderRows(
          sql5`select count(*)::int as n from ${sql5.raw(`neon_auth."${table}"`)} where ${sql5.raw(`"${column}"`)} = ${neonId}`
        );
        if (before > 0) {
          await db.execute(
            sql5`delete from ${sql5.raw(`neon_auth."${table}"`)} where ${sql5.raw(`"${column}"`)} = ${neonId}`
          );
        }
        const bucket = table === "session" ? "sessions" : table === "account" ? "accounts" : table === "member" ? "members" : "invitations";
        neonAuth[bucket] = before;
      }
      const identifier = (row.email ?? "").trim().toLowerCase();
      if (identifier) {
        neonAuth.verifications = await countProviderRows(
          sql5`select count(*)::int as n from neon_auth."verification" where "identifier" = ${identifier}`
        );
        if (neonAuth.verifications > 0) {
          await db.execute(sql5`delete from neon_auth."verification" where "identifier" = ${identifier}`);
        }
      }
      neonAuth.users = await countProviderRows(
        sql5`select count(*)::int as n from neon_auth."user" where "id" = ${neonId}`
      );
      if (neonAuth.users > 0) {
        await db.execute(sql5`delete from neon_auth."user" where "id" = ${neonId}`);
      }
    } catch (e) {
      console.error("[delete-user] provider cleanup failed; local account removal proceeds", e);
    }
  }
  const removed = await db.delete(users).where(eq3(users.id, userId)).returning({ id: users.id });
  if (removed.length === 0) return null;
  return { id: row.id, email: row.email, role: row.role, neonAuth };
}
