// shared/promo.ts
var PROMO_SETTING_KEYS = {
  new_arrivals: "promo_new_arrivals_product_id",
  best_sellers: "promo_best_sellers_product_id"
};
function discountPercent(p) {
  const was = p.compareAtCents;
  if (typeof was !== "number" || was <= p.priceCents) return null;
  return Math.round((1 - p.priceCents / was) * 100);
}
function hasRating(p) {
  return typeof p.rating === "number" && p.rating > 0 && (p.reviewCount ?? 0) > 0;
}
function promoEyebrow(kind) {
  return kind === "new_arrivals" ? "Just landed" : "Featured";
}
function promoCardCopy(kind, p) {
  const off = discountPercent(p);
  const rated = hasRating(p);
  const rating = rated ? p.rating.toFixed(1) : "";
  const count3 = p.reviewCount ?? 0;
  if (kind === "new_arrivals") {
    const body2 = off ? `New this week - now ${off}% off.` : rated ? `New this week - rated ${rating} out of 5 by ${count3} shopper${count3 === 1 ? "" : "s"}.` : "New this week - the latest addition to the range.";
    return { eyebrow: promoEyebrow(kind), title: p.name, body: body2, cta: "Shop now" };
  }
  const body = rated ? `Loved by ${count3} shopper${count3 === 1 ? "" : "s"} - ${rating} out of 5.` : off ? `Now ${off}% off.` : "Handpicked by us - a solid everyday pick.";
  return { eyebrow: promoEyebrow(kind), title: p.name, body, cta: "Shop now" };
}
function pickPromoProduct(selectedId, candidates, excludeId) {
  if (candidates.length === 0) return null;
  const wanted = (selectedId ?? "").trim();
  if (wanted) {
    const match = candidates.find((c) => c.id === wanted);
    if (match) return { product: match, source: "selected" };
  }
  const avoid = (excludeId ?? "").trim();
  const first = avoid ? candidates.find((c) => c.id !== avoid) ?? candidates[0] : candidates[0];
  return { product: first, source: "fallback" };
}

// server/promo.ts
async function resolveSlot(kind, selectedId, fallbackCandidates, excludeId) {
  const wanted = (selectedId ?? "").trim();
  let candidates = [...fallbackCandidates];
  if (wanted) {
    const [picked] = await getActiveProductsByIds([wanted]);
    if (picked) candidates = [picked, ...candidates.filter((c) => c.id !== picked.id)];
  }
  const chosen = pickPromoProduct(wanted, candidates, excludeId);
  if (!chosen) return null;
  return {
    kind,
    product: chosen.product,
    copy: promoCardCopy(kind, chosen.product),
    source: chosen.source
  };
}
async function resolvePromoSlots() {
  const settings = await getSettings();
  const [newest, best] = await Promise.all([
    listProducts({ sort: "newest", limit: 8 }),
    mostOrderedProducts(8)
  ]);
  const asId = (v) => v == null ? "" : String(v);
  const newArrivals = await resolveSlot(
    "new_arrivals",
    asId(settings[PROMO_SETTING_KEYS.new_arrivals]),
    newest
  );
  const bestSellers = await resolveSlot(
    "best_sellers",
    asId(settings[PROMO_SETTING_KEYS.best_sellers]),
    best,
    newArrivals?.product.id
  );
  return { new_arrivals: newArrivals, best_sellers: bestSellers };
}

