// server/_core/email-routing.ts
var CRITICAL_EMAIL_KINDS = [
  "order_confirmation",
  "payment_confirmation",
  "shipping_notification",
  "admin_new_order",
  // The unpaid-order alert is an OWNER alert about money that has not arrived -
  // losing it means an order is never chased, so it belongs on the critical
  // transport alongside the other order mail.
  "unpaid_alert"
];
function isCriticalEmail(kind) {
  return CRITICAL_EMAIL_KINDS.includes(kind);
}
function providerForKind(kind) {
  return isCriticalEmail(kind) ? "resend" : "smtp";
}

// server/_core/smtp.ts
init_env();
import nodemailer from "nodemailer";
var SMTP_X_MAILER = "PetParcel";
function smtpConfigured() {
  return Boolean(env.email.smtpHost && env.email.smtpUser && env.email.smtpPass);
}
async function sendViaSmtp(input) {
  const to = (input.to ?? "").trim();
  if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(to)) {
    return { status: "failed", reason: `Not a valid recipient address: "${input.to}"` };
  }
  if (!smtpConfigured()) {
    console.warn(
      "[email] BREVO_SMTP_HOST/BREVO_SMTP_USER/BREVO_SMTP_PASS are not set - skipping secondary send (add them in Settings \u2192 Environment variables)."
    );
    return {
      status: "skipped",
      reason: "BREVO_SMTP_HOST/BREVO_SMTP_USER/BREVO_SMTP_PASS are not set - add them in Settings \u2192 Environment variables to send this email."
    };
  }
  try {
    const transport = nodemailer.createTransport({
      host: env.email.smtpHost,
      port: env.email.smtpPort,
      // Implicit TLS on 465; STARTTLS upgrade on 587/2525. The relay's own
      // certificate is verified - we never disable that.
      secure: env.email.smtpSecure,
      auth: { user: env.email.smtpUser, pass: env.email.smtpPass },
      connectionTimeout: 15e3,
      greetingTimeout: 15e3,
      socketTimeout: 2e4
    });
    const info = await transport.sendMail({
      from: input.from,
      to,
      subject: input.subject,
      html: input.html,
      ...input.text ? { text: input.text } : {},
      ...input.replyTo ? { replyTo: input.replyTo } : {},
      // The brand's own mailer identity, with any caller-supplied header able to
      // override it (the newsletter, for example, has none of its own). This is
      // what keeps a library/relay fingerprint off customer-facing mail.
      headers: { "X-Mailer": env.email.smtpXMailer || SMTP_X_MAILER, ...input.headers ?? {} }
    });
    return { status: "sent", providerMessageId: info.messageId ?? null };
  } catch (e) {
    return { status: "failed", reason: `Could not send via SMTP: ${e.message}` };
  }
}

