// server/services/cj-sync.ts
init_db();
init_schema();
import { and as and6, eq as eq8, isNotNull as isNotNull2, isNull as isNull5, sql as sql7 } from "drizzle-orm";
init_db2();
var dbStore2 = {
  async listOrdersAwaitingTracking(limit) {
    const rows = await db.select({ id: orders.id, orderNumber: orders.orderNumber, cjOrderId: orders.cjOrderId }).from(orders).where(and6(eq8(orders.paymentStatus, "paid"), isNotNull2(orders.cjOrderId), isNull5(orders.trackingNumber))).limit(limit);
    return rows.map((r) => ({ id: r.id, orderNumber: r.orderNumber, cjOrderId: r.cjOrderId }));
  },
  async applyTracking(input) {
    await updateOrderTracking({
      orderId: input.orderId,
      trackingNumber: input.trackingNumber,
      carrier: input.carrier,
      note: input.note
    });
  },
  async listVariantsWithVid(limit) {
    const rows = await db.select({
      id: productVariants.id,
      sku: productVariants.sku,
      cjVid: productVariants.cjVid,
      inventoryQty: productVariants.inventoryQty
    }).from(productVariants).where(isNotNull2(productVariants.cjVid)).limit(limit);
    return rows.map((r) => ({ id: r.id, sku: r.sku, cjVid: r.cjVid, inventoryQty: r.inventoryQty }));
  },
  async setVariantStock(variantId, qty) {
    await db.update(productVariants).set({ inventoryQty: qty }).where(eq8(productVariants.id, variantId));
  }
};
async function runTrackingSync(deps = {}) {
  const client = deps.client ?? cjClient;
  const store = deps.store ?? dbStore2;
  const summary = { checked: 0, updated: 0, skipped: 0, failed: 0, held: 0 };
  if (!client.isConfigured()) {
    console.log("[cj-tracking-sync] skipped: CJ_API_KEY is not set (integration not configured).");
    return summary;
  }
  const rows = await store.listOrdersAwaitingTracking(deps.limit ?? 50);
  for (const row of rows) {
    summary.checked += 1;
    try {
      const detail = await client.getOrderDetail(row.cjOrderId);
      const tracking = (detail.trackNumber ?? "").trim();
      if (!tracking) {
        summary.skipped += 1;
        continue;
      }
      const carrier = detail.trackingProvider ?? detail.logisticName ?? null;
      await store.applyTracking({
        orderId: row.id,
        trackingNumber: tracking,
        carrier,
        note: `Tracking synced from CJ (${carrier ?? "carrier"} ${tracking})`
      });
      summary.updated += 1;
      console.log(`[cj-tracking-sync] order ${row.orderNumber} \u2192 ${tracking}`);
    } catch (err) {
      summary.failed += 1;
      const reason = err instanceof CjNotConfiguredError ? "not_configured" : err instanceof Error ? err.message : String(err);
      console.error(`[cj-tracking-sync] order ${row.orderNumber} failed: ${reason}`);
    }
  }
  console.log(
    `[cj-tracking-sync] done. checked=${summary.checked} updated=${summary.updated} skipped=${summary.skipped} failed=${summary.failed}`
  );
  return summary;
}
function totalStock(rows, opts = {}) {
  if (opts.ignoreZeros) {
    const positive = rows.map((r) => Number(r.totalInventoryNum) || 0).filter((n) => n > 0);
    if (positive.length > 0) return positive.reduce((a, b) => a + b, 0);
  }
  return rows.reduce((sum, r) => sum + (Number(r.totalInventoryNum) || 0), 0);
}
var CJ_STOCK_FLOOR = 5;
function isSuspiciousStockDrop(previous, next, floor = CJ_STOCK_FLOOR) {
  return next === 0 && previous >= floor;
}
async function runStockSync(deps = {}) {
  const client = deps.client ?? cjClient;
  const store = deps.store ?? dbStore2;
  const summary = { checked: 0, updated: 0, skipped: 0, failed: 0, held: 0 };
  if (!client.isConfigured()) {
    console.log("[cj-stock-sync] skipped: CJ_API_KEY is not set (integration not configured).");
    return summary;
  }
  const rows = await store.listVariantsWithVid(deps.limit ?? 200);
  for (const row of rows) {
    summary.checked += 1;
    try {
      const stock = await client.queryStockByVid(row.cjVid);
      const total = Math.max(0, Math.floor(totalStock(stock, { ignoreZeros: true })));
      if (total === row.inventoryQty) {
        summary.skipped += 1;
        continue;
      }
      if (isSuspiciousStockDrop(row.inventoryQty, total)) {
        summary.held += 1;
        console.warn(
          `[cj-stock-sync] ${row.sku}: CJ reported 0 (was ${row.inventoryQty}) - held, not written. Confirm in CJ, then set the stock by hand if it is genuinely out of stock.`
        );
        continue;
      }
      await store.setVariantStock(row.id, total);
      summary.updated += 1;
      console.log(`[cj-stock-sync] ${row.sku} ${row.inventoryQty} \u2192 ${total}`);
    } catch (err) {
      summary.failed += 1;
      const reason = err instanceof CjNotConfiguredError ? "not_configured" : err instanceof Error ? err.message : String(err);
      console.error(`[cj-stock-sync] ${row.sku} failed: ${reason}`);
    }
  }
  console.log(
    `[cj-stock-sync] done. checked=${summary.checked} updated=${summary.updated} skipped=${summary.skipped} held=${summary.held} failed=${summary.failed}`
  );
  return summary;
}

