        orderNumber: order.orderNumber,
        email: order.email,
        customerName: order.shippingAddress?.fullName || "there",
        totalCents: order.totalCents,
        currency: order.currency,
        createdAt: order.createdAt,
        paymentStatus: order.paymentStatus,
        orderUrl: orderUrl2
