// server/services/telegram-outbox.ts
init_db2();
var OUTBOX_MAX_ATTEMPTS = 5;
var OUTBOX_SWEEP_BATCH = 25;
async function runTelegramOutboxSweep(deps) {
  const due = await claimDueTelegramOutbox(OUTBOX_SWEEP_BATCH);
  const result = {
    claimed: due.length,
    sent: 0,
    retried: 0,
    failed: 0,
    already: 0,
    skipped: 0,
    sentOrders: []
  };
  for (const row of due) {
    try {
      const outcome = await notifyPaidOrderOnce({
        orderId: row.orderId,
        trigger: "outbox",
        deps
      });
      if (outcome.status === "sent") {
        await markTelegramOutboxSent(row.id);
        result.sent += 1;
        result.sentOrders.push(row.orderNumber);
        continue;
      }
      if (outcome.status === "already_notified") {
        await markTelegramOutboxSent(row.id);
        result.already += 1;
        continue;
      }
      if (outcome.status === "not_delivered") {
        const { status } = await recordTelegramOutboxFailure(
          row.id,
          outcome.reason,
          OUTBOX_MAX_ATTEMPTS
        );
        if (status === "failed") result.failed += 1;
        else result.retried += 1;
        continue;
      }
      result.skipped += 1;
      if (outcome.status === "no_order") {
        await markTelegramOutboxSent(row.id);
      }
    } catch (e) {
      const reason = `Sweep error: ${e.message}`;
      const { status } = await recordTelegramOutboxFailure(
        row.id,
        reason,
        OUTBOX_MAX_ATTEMPTS
      ).catch(() => ({ status: "pending", attempts: 0 }));
      if (status === "failed") result.failed += 1;
      else result.retried += 1;
    }
  }
  return result;
}
registerJob("telegram-outbox", async () => {
  const result = await runTelegramOutboxSweep();
  console.log(
    `[telegram-outbox] claimed=${result.claimed} sent=${result.sent} retried=${result.retried} failed=${result.failed} already=${result.already} skipped=${result.skipped}` + (result.sentOrders.length ? ` delivered=${result.sentOrders.join(",")}` : "")
  );
});

